#!/usr/bin/env bash
#
# Every tests/corpus/nsedge/*.proto must be regenerated by the golden scripts and have a checked-in
# streamgen AND arenagen golden.
#
# Why a dedicated check: nothing else notices a fixture that has NO golden. regen_goldens.sh only
# flags a golden that exists but was not regenerated -- the reverse direction -- and the per-model
# case lists in test_streamgen.cpp / test_arenagen.cpp / test_dumpgen.cpp are hand-maintained. So a
# .proto dropped into nsedge/ silently gets no golden and no streaming coverage at all. That has
# happened twice. (The differential does pick up any corpus schema by rglob and compiles it under
# --arena --dump, so the gap is narrower than "untested" -- but it pins no generated text, and it
# skips itself when protoc is absent.)
#
# nsedge is where package/namespace SHAPES are pinned, and several of them fail in ways no compiler
# can see: a package named `std` emits `namespace std { ... }`, undefined behaviour that compiles
# without a diagnostic. A byte-compared golden is the only thing that catches a regression there.
#
# Checking the regen reference, not just the file, is what makes this more than a touch-two-files
# test: it ties the fixture to the script that rebuilds its golden, and it stops an unrelated
# directory's golden of the same stem from satisfying the rule (golden paths are a flat namespace,
# so tests/corpus/nsedge/proto3.proto would otherwise be "covered" by tests/corpus/proto3.proto's).
#
# The dump model is deliberately not required. Its namespace comes from the same shared
# CppNameTable the arena golden pins, so a dump-only namespace regression is not reachable. Add a
# dump golden anyway when a fixture's dump OUTPUT is the point (stdpkg/rppkg have one).
set -euo pipefail
cd "$(dirname "$0")/.."

readonly NSEDGE=tests/corpus/nsedge

mapfile -t protos < <(find "$NSEDGE" -name '*.proto' | sort)
if [[ ${#protos[@]} -eq 0 ]]; then
  echo ">> no fixtures found under $NSEDGE/ -- this check is looking in the wrong place"
  exit 1
fi

missing=0
for proto in "${protos[@]}"; do
  stem="$(basename "$proto" .proto)"

  # Coexistence fixtures are pinned differently, and must be: their whole point is a TU holding BOTH
  # models, which needs ONE shared common header -- so they are generated by a single both-models
  # invocation into tests/coexist_golden/ (regen_goldens.sh [4b/5]) rather than once per model dir.
  # Two per-model copies of that header duplicate every enum in such a TU.
  if [[ -s "tests/coexist_golden/$stem.rp.hpp" && -s "tests/coexist_golden/$stem.rp.stream.hpp" ]]; then
    for model in "rp.hpp|arena" "rp.stream.hpp|stream"; do
      if ! grep -q "coexist_golden/$stem.${model%%|*}" tests/test_coexistence.cpp; then
        echo ">> $proto: tests/test_coexistence.cpp never includes its ${model##*|} header --"
        echo "   that TU exists to hold BOTH models at once, so one of them is not being tested"
        missing=1
      fi
    done
    # Being INCLUDED only proves it compiles. check_pair's stem list is what byte-compares it, and
    # that list is hand-maintained -- trimming it leaves the golden unpinned with the suite green.
    if ! grep -q "\"$stem\"" tests/test_coexistence.cpp; then
      echo ">> $proto is included by tests/test_coexistence.cpp but absent from check_pair's stem"
      echo "   list, so its goldens are compiled and never compared"
      missing=1
    fi
    # Only the per-model golden check is skipped; regeneration is still verified below.
    coexist=1
  else
    coexist=0
  fi

  # -s, not -f: an empty golden is not a golden.
  #
  # A golden FILE is not coverage: what pins the fixture is a test that byte-compares it. Checking
  # only for the file let a stem be dropped from a suite's case list while this stage kept printing
  # its usual totals -- and the fixture it hid that way was `stdpkg` (`package std`), whose whole
  # point is that no compiler catches it. So each golden is required to be named by the suite that
  # compares it, the same way the coexistence branch above requires check_pair's stem list.
  if [[ $coexist -eq 0 ]]; then
    for want in "tests/streamgen_golden/$stem.rp.stream.hpp|--stream|tests/test_streamgen.cpp" \
                "tests/arenagen_golden/$stem.rp.hpp|--arena|tests/test_arenagen.cpp"; do
      IFS='|' read -r path model suite <<<"$want"
      if [[ ! -s "$path" ]]; then
        echo ">> $proto has no $model golden ($path)"
        missing=1
      elif ! grep -q "\"$stem\"" "$suite"; then
        echo ">> $proto has a $model golden that $suite never compares (no \"$stem\" case)"
        missing=1
      fi
    done
  fi

  # Regenerated either directly, or transitively as an import of a fixture that is (deep.proto is
  # pulled in by xpkg.proto and has no entry of its own).
  # `grep -v` on the fixture itself: a self-importing fixture (`import "bogus.proto";` inside
  # bogus.proto) otherwise claims the transitive exemption and skips BOTH regen checks.
  imported_by="$(grep -l "import \"$stem.proto\"" "$NSEDGE"/*.proto 2>/dev/null | grep -v "^$proto$" || true)"
  scripts=(tests/regen_goldens.sh tests/regen_arenagen_goldens.sh)
  [[ $coexist -eq 1 ]] && scripts=(tests/regen_goldens.sh)  # one both-models entry covers it
  for script in "${scripts[@]}"; do
    if ! grep -q "$NSEDGE/$stem.proto" "$script" && [[ -z "$imported_by" ]]; then
      echo ">> $proto is not regenerated by $script (no entry, and nothing imports it)"
      missing=1
    fi
  done
done

# Two byte-identical goldens reaching ONE translation unit are both a lost test and a portability
# trap: gcc's content-keyed `#pragma once` silently collapses them, clang rejects the second as a
# redefinition. This is why a `_prefixed` golden must use a NON-default prefix -- at the default it
# is byte-for-byte its unprefixed twin, and tests/test_streamgen.cpp pulls in both.
#
# The include CLOSURE, from the preprocessor, not the `#include` lines: the headers that actually
# collide are the shared `*.rp.common.hpp`, which no test names directly -- each decoder golden
# pulls its own in. Reading the source would miss exactly the case this exists for. `-M -MG` costs
# no codegen and treats a header it cannot find as a leaf rather than failing.
#
# Per TU, not tree-wide: identical goldens in DIFFERENT directories (arenagen_golden/x.rp.hpp and
# dumpgen_golden/x.rp.hpp) are a known, deliberate duplication that no single TU pulls in together.
#
# The preprocessor's exit status is CHECKED, not swallowed. Discarding it made every failure look
# like an empty closure -- no g++, a wrapper that exits non-zero, a renamed golden dir -- so the
# scan compared nothing and the stage passed on a tree that had the very defect it looks for.
dupes=""
for tu in tests/test_*.cpp; do
  if ! raw="$(g++ -std=c++17 -M -MG -I include -I tests -I tests/arenagen_golden \
                  -I tests/streamgen_golden -I tests/dumpgen_golden -I tests/coexist_golden \
                  "$tu" 2>&1)"; then
    echo ">> the duplicate-golden scan could not preprocess $tu -- it checked nothing:"
    sed 's/^/   /' <<<"$raw" | head -3
    missing=1
    continue
  fi
  closure="$(tr ' \\' '\n\n' <<<"$raw" | { grep -E 'tests/.*golden.*\.hpp$' || true; } | sort -u)"
  hits="$(while read -r f; do
            [[ -s "$f" ]] || continue
            grep -qE '^(class|struct|enum class|inline|template)' "$f" || continue
            echo "$(sha256sum "$f" | cut -d' ' -f1) $f"
          done <<<"$closure" \
          | sort | awk -v tu="$tu" '{ if ($1==prev && $1!="") { print tu": "prevf" == "$2 } prev=$1; prevf=$2 }' || true)"
  if [[ -n "$hits" ]]; then
    dupes+="$hits"$'\n'
  fi
done
if [[ -n "${dupes// /}" ]]; then
  echo ">> byte-identical goldens reach one TU -- clang rejects the second as a redefinition:"
  sed 's/^/   /' <<<"$dupes" | grep -v '^   $'
  missing=1
fi

if [[ $missing -ne 0 ]]; then
  echo ">> Add the fixture to tests/regen_goldens.sh and tests/regen_arenagen_goldens.sh, plus its"
  echo ">> case list and #include in the matching test file. Seed each golden once by running"
  echo ">> rapidprotoc directly (the regen scripts only overwrite goldens that already exist),"
  echo ">> then re-run tests/regen_goldens.sh."
  exit 1
fi
echo "fixture coverage: ${#protos[@]} nsedge schemas, each regenerated and pinned by a golden a test compares"
